/*
 * 14.cpp
 *
 * Dynamic Boolean truth-arithmetic acceptance engine for Book Sport tables
 * generated by 13.cpp.
 *
 * Purpose:
 *   - Load the static formal Book Sport table emitted by 13.cpp.
 *   - Treat row headings and column headings as pointers to instructional
 *     semantic structures.
 *   - Recompute and verify pointer hashes, semantic hashes, and cell identity
 *     hashes before evaluation.
 *   - Dynamically evaluate Boolean acceptance contracts.
 *   - Enforce hard barriers: a cell remains closed unless its selected Boolean
 *     expression evaluates to true.
 *   - Emit escaped, replayable, information-identity-preserving acceptance
 *     event records for downstream engineering architecture workflows.
 *
 * Build:
 *   c++ -std=c++17 -Wall -Wextra -pedantic -O2 14.cpp -o 14
 *
 * Examples:
 *   ./14 --table engineering_architecture_book_sport.table.txt
 *   ./14 --table engineering_architecture_book_sport.table.txt \
 *        --rules book_sport_14.rules \
 *        --facts book_sport_14.facts \
 *        --execute --overwrite --all \
 *        --output-target book_sport_14.acceptance.events.txt
 *
 * Rule examples:
 *   default=false
 *   column:observe=integrity_ok AND semantic_present
 *   x_measurement.validate=integrity_ok AND semantic_present AND measurement_verified
 *   x_boundary->barrier_check=integrity_ok AND hard_barrier AND operator_authorized
 *   cell:51c2faea9bd8ce7c=integrity_ok AND measurement_verified
 *
 * Boolean expression grammar:
 *   literals: true false 1 0 yes no on off
 *   unary:    NOT a, !a
 *   binary:   a AND b, a && b, a & b
 *             a NAND b
 *             a OR b,  a || b, a | b
 *             a NOR b
 *             a XOR b, a ^ b
 *             a XNOR b, a EQV b, a EQUIV b
 *             a IMPLY b, a -> b
 *   grouping: ( ... )
 *
 * Built-in variables per cell include:
 *   integrity_ok, row_hash_ok, column_hash_ok, row_semantic_hash_ok,
 *   column_semantic_hash_ok, cell_identity_ok, semantic_present,
 *   row_semantic_present, column_semantic_present, hard_barrier,
 *   boolean_engine_is_14, contract_present, barrier_policy_known,
 *   row__<sanitized_row_pointer>, column__<sanitized_column_pointer>.
 */

